const body = $('Webhook').first().json.body;

const chartType = body.chart_type || 'bar';
const title = body.title || '';
const data = body.data;
const options = body.options || {};

// Build Chart.js configuration
let chartConfig = {
  type: chartType,
  data: {},
  options: {
    responsive: true,
    plugins: {
      title: {
        display: !!title,
        text: title
      },
      legend: {
        display: options.show_legend !== false
      }
    }
  }
};

// Handle different data formats
if (Array.isArray(data)) {
  // Simple array format: [{label: 'A', value: 10}, {label: 'B', value: 20}]
  const labels = data.map(d => d.label || d.name || d.x || '');
  const values = data.map(d => d.value || d.y || d.count || 0);

  chartConfig.data = {
    labels: labels,
    datasets: [{
      label: body.dataset_label || 'Data',
      data: values,
      backgroundColor: options.colors || [
        'rgba(54, 162, 235, 0.8)',
        'rgba(255, 99, 132, 0.8)',
        'rgba(255, 206, 86, 0.8)',
        'rgba(75, 192, 192, 0.8)',
        'rgba(153, 102, 255, 0.8)',
        'rgba(255, 159, 64, 0.8)'
      ]
    }]
  };
} else if (data.labels && data.datasets) {
  // Chart.js native format
  chartConfig.data = data;
} else if (data.labels && data.values) {
  // Simple labels + values format
  chartConfig.data = {
    labels: data.labels,
    datasets: [{
      label: body.dataset_label || 'Data',
      data: data.values,
      backgroundColor: options.colors || 'rgba(54, 162, 235, 0.8)'
    }]
  };
}

// Special handling for pie/doughnut charts
if (['pie', 'doughnut'].includes(chartType)) {
  chartConfig.options.plugins.legend.position = options.legend_position || 'right';
}

// Special handling for line charts
if (chartType === 'line') {
  if (chartConfig.data.datasets) {
    chartConfig.data.datasets = chartConfig.data.datasets.map(ds => ({
      ...ds,
      fill: options.fill !== false,
      tension: options.tension || 0.1
    }));
  }
}

return [{
  json: {
    chartConfig: chartConfig,
    width: body.width || 600,
    height: body.height || 400,
    format: body.format || 'png',
    backgroundColor: body.background_color || 'white'
  }
}];

const items = $input.all();
const webhookData = $('Webhook').first().json;
const chartData = $('Build Chart Config').first().json;

const results = items.map(item => {
  if (item.json.error) {
    return {
      json: {
        success: false,
        error: {
          code: 500,
          message: item.json.error.message || 'Chart generation failed',
          status: 'CHART_ERROR'
        },
        meta: { provider: 'quickchart' }
      }
    };
  }

  // QuickChart returns the image URL or base64
  const chartUrl = `https://quickchart.io/chart?c=${encodeURIComponent(JSON.stringify(chartData.chartConfig))}&w=${chartData.width}&h=${chartData.height}&bkg=${encodeURIComponent(chartData.backgroundColor)}`;

  return {
    json: {
      success: true,
      data: {
        chart_url: chartUrl,
        chart_config: chartData.chartConfig,
        dimensions: {
          width: chartData.width,
          height: chartData.height
        },
        format: chartData.format
      },
      meta: {
        provider: 'quickchart',
        chart_type: chartData.chartConfig.type
      }
    }
  };
});

return results;
